code:
resource "aws_instance" "app" {
  ami           = "ami-0c55b159cbfafe1f0"
  instance_type = "t2.micro"
  tags = {
    Name = "education-app"
  }
}

output "public_ip" {
  value = aws_instance.app.public_ip
}

server {
  listen 80;
  server_name education.com;

  location / {
    proxy_pass http://localhost:3000;
    proxy_set_header Host $host;
    proxy_set_header X-Real-IP $remote_addr;
  }
}

server {
  listen 443 ssl http2;
  server_name education.com;

  ssl_certificate /etc/letsencrypt/live/education.com/fullchain.pem;
  ssl_certificate_key /etc/letsencrypt/live/education.com/privkey.pem;

  location / {
    proxy_pass http://localhost:3000;
  }
}

module.exports = {
  apps: [
    {
      name: "education-api",
      script: "./server.js",
      instances: 4,
      exec_mode: "cluster",
      env: {
        NODE_ENV: "production"
      }
    }
  ]
};

{
  "dashboard": {
    "title": "Education Platform",
    "panels": [
      {
        "title": "Requests per second",
        "targets": [{
          "expr": "rate(http_requests_total[1m])"
        }]
      }
    ]
  }
}

input {
  tcp {
    port => 5000
    codec => json
  }
}

filter {
  if [service] == "education-api" {
    mutate { add_tag => ["api"] }
  }
}

output {
  elasticsearch {
    hosts => ["localhost:9200"]
  }
}

pipeline {
  agent any
  stages {
    stage('Build') {
      steps {
        sh 'npm install && npm run build'
      }
    }
    stage('Test') {
      steps {
        sh 'npm test'
      }
    }
    stage('Deploy') {
      steps {
        sh 'docker build -t education:latest .'
        sh 'docker push education:latest'
      }
    }
  }
}

resource "aws_vpc" "education" {
  cidr_block = "10.0.0.0/16"

  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "education-vpc"
  }
}

resource "aws_s3_bucket" "education_videos" {
  bucket = "education-videos-2024"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

resource "aws_cloudfront_distribution" "education" {
  origin {
    domain_name = aws_s3_bucket.education_videos.bucket_regional_domain_name
    origin_id   = "myS3Origin"
  }

  enabled = true

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "myS3Origin"
  }
}

resource "aws_dynamodb_table" "sessions" {
  name           = "education-sessions"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "session_id"

  attribute {
    name = "session_id"
    type = "S"
  }

  ttl {
    attribute_name = "expires_at"
    enabled        = true
  }
}

exports.handler = async (event) => {
  const courseId = event.pathParameters.courseId;
  const course = await getCourseFromDB(courseId);

  return {
    statusCode: 200,
    body: JSON.stringify(course)
  };
};

resource "aws_api_gateway_rest_api" "education" {
  name = "education-api"

  endpoint_configuration {
    types = ["REGIONAL"]
  }
}

resource "aws_api_gateway_resource" "courses" {
  rest_api_id = aws_api_gateway_rest_api.education.id
  parent_id   = aws_api_gateway_rest_api.education.root_resource_id
  path_part   = "courses"
}

resource "aws_lb" "education" {
  name               = "education-lb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb.id]
  subnets            = aws_subnet.public[*].id
}

resource "aws_lb_target_group" "education" {
  name     = "education-tg"
  port     = 3000
  protocol = "HTTP"
  vpc_id   = aws_vpc.education.id
}

resource "aws_security_group" "app" {
  name = "education-app-sg"

  ingress {
    from_port   = 3000
    to_port     = 3000
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
